@app.cell
def _(WORK_ROOT, mo, os, wc):
    os.environ.setdefault("PYTORCH_CUDA_ALLOC_CONF", "expandable_segments:True")
    import pandas as pd
    with mo.status.spinner(title="Training env (torch + open_clip): built once per machine (~5-10 min), then probed"):
        TRAIN_PY = wc.ensure_train_env(WORK_ROOT)
    return TRAIN_PY, pd


@app.cell
def _(EXP_ID, HF_TOKEN, NOTEBOOK, WORK_ROOT, wc):
    hub = wc.Hub(HF_TOKEN)
    hub.ensure_outputs_repo()
    hub.put({"code/sclr_common.py": WORK_ROOT / "common" / "sclr_common.py"}, f"shared module {wc.VERSION}")
    SETUP_RUN = f"{wc.ARCH}-setup"
    wb_run, log_fn = wc.wandb_init(
        SETUP_RUN, "setup", [f"exp:{EXP_ID}", f"nb:{NOTEBOOK}", f"arch:{wc.ARCH}", "user:emmilly"],
        {"exp_id": EXP_ID, "notebook": NOTEBOOK, "module_version": wc.VERSION, "git_commit": "unknown",
         "packages": wc.package_versions(("numpy", "pandas", "huggingface_hub", "wandb", "marimo"))})
    RES_CSV = WORK_ROOT / "runs" / SETUP_RUN / "resources.csv"
    return RES_CSV, hub, log_fn, wb_run


@app.cell
def _(DATA_ROOT, RES_CSV, STAGES, TRAIN_PY, WORK_ROOT, log_fn, wc):
    data_report = None
    if STAGES["data"]:
        try:
            with wc.track_resources("data", log_fn=log_fn, csv_path=RES_CSV):
                _r = wc.run_or_attach("00_data", TRAIN_PY, "setup_main",
                                      {"work_root": str(WORK_ROOT), "data_root": str(DATA_ROOT), "mode": "data"}, WORK_ROOT, timeout_h=6)
                if _r["rc"] != 0 or not _r["results"]:
                    raise RuntimeError("\n".join(_r["tail"][-15:]))
            data_report = _r["results"][-1]
            print(f"[data] OK | {DATA_ROOT / 'iwildcam_v2.0'} | split sizes {data_report.get('split_sizes')}")
        except RuntimeError as _e:
            print(f"[data] FAILED (benchmark skipped). Last lines:\n{_e}")
    else:
        data_report = {"source": "stage switched off"}
        print("[data] switched off: the benchmark assumes the data is at DATA_ROOT")
    return (data_report,)


@app.cell
def _(BENCH_BATCHES, BENCH_BATCH_SIZES, DATA_ROOT, FORCE, HPARAMS, RES_CSV, STAGES, TRAIN_PY, WORK_ROOT, data_report, hub, json, log_fn, wc):
    bench = None
    _local = WORK_ROOT / "benchmark.json"  # machine-specific, so the marker is local
    if data_report is None:
        print("[benchmark] skipped: no data")
    elif STAGES["benchmark"] and (not _local.exists() or "benchmark" in FORCE):
        try:
            with wc.track_resources("benchmark", log_fn=log_fn, csv_path=RES_CSV):
                _r = wc.run_or_attach("00_benchmark", TRAIN_PY, "setup_main",
                                      {"work_root": str(WORK_ROOT), "data_root": str(DATA_ROOT), "mode": "benchmark",
                                       "hparams": HPARAMS, "batch_sizes": BENCH_BATCH_SIZES, "n_batches": BENCH_BATCHES},
                                      WORK_ROOT, timeout_h=2)
                if _r["rc"] != 0 or not _r["results"]:
                    raise RuntimeError("\n".join(_r["tail"][-15:]))
            bench = _r["results"][-1]
            wc.write_json(_local, bench)
            hub.put({wc.manifest_path(f"throughput__{bench['host']}.json"): _local}, f"throughput on {bench['host']}")
            print(f"[benchmark] OK | {bench}")
        except RuntimeError as _e:
            print(f"[benchmark] FAILED. Last lines:\n{_e}")
    elif _local.exists():
        bench = json.loads(_local.read_text())
        print(f"[benchmark] read back from {_local}")
    return (bench,)


@app.cell
def _(BENCH_BATCH_SIZES, bench, data_report, log_fn, mo, pd, wb_run, wc):
    _rows = [("data", "OK" if data_report else "FAILED", "" if not data_report else str(data_report.get("split_sizes", "")))]
    _advice = ""
    if bench:
        _ok = {b: bench.get(f"gpu_train_img_s_b{b}") for b in BENCH_BATCH_SIZES}
        _fits = {b: v for b, v in _ok.items() if isinstance(v, (int, float))}
        _best_bs = max(_fits, key=_fits.get) if _fits else None
        _rows.append(("weights", "OK", f"{bench['model']} / {bench['pretrained']}: {bench['n_params_visual_M']}M visual params, "
                      f"image size {bench['image_size']}, class names from {bench['class_names_from']}"))
        _rows.append(("benchmark", "OK", "; ".join(f"batch {b}: {v} img/s, peak {bench.get(f'peak_gpu_mem_gb_b{b}')} GB"
                                                  for b, v in _ok.items()) + f"; eval {bench['gpu_eval_img_s']} img/s; "
                      f"loader {bench['data_train_img_s']} img/s"))
        if _best_bs:
            _advice = (f"**For 01_train_dfn_vith14.py:** `batch_size = {_best_bs}` is fastest ({_fits[_best_bs]} img/s). "
                       f"At the configured batch size: ~{bench.get('est_epoch_h', '?')} h per epoch, ~{bench.get('est_run_h', '?')} h "
                       f"per run (all epochs plus the zero-shot and train-feature passes).")
        if log_fn:
            log_fn({k: v for k, v in bench.items() if isinstance(v, (int, float))}, summary=True)
    wc.wandb_finish(wb_run)
    mo.vstack([mo.md("## Setup summary"), mo.ui.table(pd.DataFrame(_rows, columns=["stage", "status", "details"]), selection=None),
               mo.md(_advice)])
    return


if __name__ == "__main__":
    app.run()
